__NUXT_JSONP__("/tr/stay", (function(a,b,c,d,e,f,g,h,i,j,k){return {data:[{details:{slug:"tr",pageTitle:"Konaklama | Mentor Language Institute",pageDescription:"MLI öğrencilerine ev sahipliği yapan U.S Destek Hizmetleri A.Ş. (USSS) ile birlikte çalışmaktadır.",title:"Konaklama",subtitle:["MLI öğrencilerine ev sahipliği yapan U.S Destek Hizmetleri A.Ş. (USSS) ile birlikte çalışmaktadır. \u003Cbr \u002F\u003EDaha fazla ayrıntı için lütfen \u003Ca href=\"www.usssinc.net\" target=\"_blank\"\u003Ewww.usssinc.net\u003C\u002Fa\u003E  adresini ziyaret edin."],image:"\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-1.jpg",gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-3.jpg"],note:"Öğrenciler ya aile ya da yurtda konaklamayi tercih edebilir.",types:[{title:"Yurt",description:["Yurtlarımızda 40 odamız bulunmaktadır. Diğer uluslararası öğrencilerle iletişim kurmak için pek çok fırsat olacak. Bütçeniz varsa yurtta kalmanızı tavsiye ederiz."],lists:["\u003Cb\u003EOda\u003C\u002Fb\u003E : Özel (Kişisel), Paylaşımlı (2 kişi) ve Dört Kişilik (4 kişi)","\u003Cb\u003EYemek\u003C\u002Fb\u003E : Yemeksiz (tam donanımlı bir mutfak mevcuttur)","\u003Cb\u003EGizlilik\u003C\u002Fb\u003E : Aile yanindan daha fazla mahremiyet vardır. Bazı yurt kuralları vardır.","\u003Cb\u003EUlaşim\u003C\u002Fb\u003E : Yürüyerek ya da otobüsle yaklaşık 20 dakika."],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-4.jpg"],prices:[{title:"Yurt Fiyatları",table:{tableMaxCol:4,title:"Yerleşim Ücreti *: 200 TL\u003Cbr \u002F\u003E 18 yaşından küçükler için kira bedeli, 18 yaşından büyükler için belirlenen fiyattan yaklaşık %10 daha yüksek olacaktır.",thead:[b,c,"Paylaşımli","Dörtlü"],tbody:[[d,a,a,a],[e,"$550","$410",a],[f,"$1,100","$820","$600"],[g,"$1,650","$1,230","$900"],[h,"$2,200","$1,640","$1,200"],[i,"$4,160","$2,960","$2,160"],[j,"$6,240","$4,440","$3,240"]]},notes:[k]}]},{title:"Aile Yani",description:["Aile yanında bir aile ile yaşamayı tercih eden öğrenciler, İngilizce becerilerini geliştirebilecekleri güvenli, sıcak ve rahat bir ortam arıyorlar. Aynı zamanda Amerikan gelenekleri, gelenekleri ve aile değerleri hakkında bilgi edinmek için bir fırsat."],lists:["\u003Cb\u003EOda\u003C\u002Fb\u003E : Özel (Bireysel)","\u003Cb\u003EÖğün\u003C\u002Fb\u003E : Günde 2 öğün (Kahvaltı ve Akşam Yemeği)","\u003Cb\u003EGizlilik\u003C\u002Fb\u003E : Ev sahibi aileye bağlı olarak bazı ev kuralları vardır.","\u003Cb\u003EGidiş\u003C\u002Fb\u003E : otobüsle 30-45 dakika"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-4.jpg"],prices:[{title:"Aile Yanında Fiyatlar",table:{tableMaxCol:3,title:"Yerleşim Ücreti *: 300 ABD doları\u003Cbr \u002F\u003E 18 yaşından küçükler için kira bedeli, 18 yaşından büyükler için belirlenen fiyattan yaklaşık %10 daha yüksek olacaktır.",thead:[b,c,"Paylaşımli***"],tbody:[[d,a,a],[e,"$436","$384"],[f,"$872","$768"],[g,"$1,308","$1,152"],[h,"$1,744","$1,536"],[i,"$3,160","$2,904"],[j,"$4,740","$4,356"]]},notes:[k]}]}],comments:{title:"Ekibimizden yorumlar",description:["Amerika'ya ilk geldiğinizde kalacak bir yer bulmak kolay değil. \u003Cbr \u002F\u003EÖzellikle Sosyal Güvenlik Numarası (SSN) ve kredi geçmişi olmayan uluslararası öğrenciler için. \u003Cbr \u002F\u003EÇoğu yerde bir yer kiralamak için hem bir SSN hem de kredi geçmişi gerekir. \u003Cbr \u002F\u003EBu nedenle, en azından ilk birkaç ay boyunca konaklama yerimizde kalmanızı öneririz.","※Konaklama ABD Destek Hizmetleri A.Ş. veya diğer acenteler tarafından sağlanacaktır."]},dir:"\u002Fstay",path:"\u002Fstay\u002Ftr",extension:".json",createdAt:"2026-10-22T16:31:31.116Z",updatedAt:"2025-05-26T12:06:27.922Z"}}],fetch:{},mutations:void 0}}("$300","","Özel","\u003Cb\u003EDepozito**\u003C\u002Fb\u003E","1 hafta","2 hafta","3 hafta","4 hafta","8 hafta","12 hafta","* Yerleşim ücreti bir defalık ödeme şeklindedir. Bu iade edilmez.\u003Cbr \u002F\u003E** Öğrenciler taşındıktan sonra güvenlik teminatı iade edilecektir.\u003Cbr \u002F\u003E*** Aile yanında bir ortak oda talep ediyorsanız, başka biriyle başvurmalısınız.")));